BEGIN; CREATE EXTENSION IF NOT EXISTS http WITH SCHEMA extensions; DO $secure$ DECLARE fn record; BEGIN FOR fn IN SELECT p.oid::regprocedure AS signature FROM pg_proc p JOIN pg_depend d ON d.objid=p.oid AND d.classid='pg_proc'::regclass JOIN pg_extension e ON e.oid=d.refobjid WHERE e.extname='http' AND d.deptype='e' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated',fn.signature); EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO postgres, service_role',fn.signature); END LOOP; END $secure$; COMMIT;
